class Solution {
public:
    vector<string> less20={""," One"," Two"," Three"," Four"," Five"," Six", " Seven"," Eight"," Nine"," Ten"," Eleven"," Twelve"," Thirteen"," Fourteen"," Fifteen"," Sixteen"," Seventeen"," Eighteen"," Nineteen"};
    vector<string> tens={""," Ten"," Twenty"," Thirty"," Forty"," Fifty"," Sixty"," Seventy"," Eighty"," Ninety"};
    vector<string> thousand={""," Thousand"," Million"," Billion"};
    string helper(int val)
    {
        if(val<20)
            return less20[val];
        if(val<100)
            return tens[val/10]+helper(val%10);
        if(val<1000)
            return helper(val/100)+" Hundred"+helper(val%100);
        for(int i=3;i>=0;i--)
        {
            if(val>=(pow(1000,i)))
                return helper(val/pow(1000,i))+thousand[i]+helper(val%(int)(pow(1000,i)));
        }
        return "";
    }
    string numberToWords(int num) {
        if(num==0)
            return "Zero";
        return helper(num).substr(1);
    }
};

class Solution(object):
    def numberToWords(self, num):
        """
        :type num: int
        :rtype: str
        """
        words_1 = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"]
        words_2 = ["Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
        words_3 = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]
        words_4 = ["", "Thousand", "Million", "Billion"]

        if num == 0:
            return "Zero"

        def toEnglish(num):
            s = ""
            if num >= 100:
                s += words_1[num // 100] + " Hundred "
                num = num % 100
            if num >= 20:
                s += words_3[num // 10] + " "
                num = num % 10
            if num >= 10:
                s += words_2[num - 10] + " "
            elif num > 0:
                s += words_1[num] + " "
            return s

        ans = ""
        cur_part = 10 ** 9
        for i in range(3, -1, -1):
            cur_num = num // cur_part
            if cur_num:
                num -= cur_num * cur_part
                ans += toEnglish(cur_num) + words_4[i] + " "
            cur_part = cur_part / 1000
        return ans.strip()
